static bool num(const string &s,u64 &v){if(s.empty())return false;v=0;for(unsigned char c:s){if(c<'0'||c>'9'||v>(ULLONG_MAX-(c-'0'))/10)return false;v=v*10+c-'0';}return true;}
static bool tok(const string&s){if(s.empty())return false;for(unsigned char c:s)if(!c||!((c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||strchr("!#$%&'*+-.^_`|~",c)))return false;return true;}
