static bool utf8(const string&s){for(size_t i=0;i<s.size();){unsigned char c=s[i++];if(c<128)continue;int n;unsigned x,lo;if(c>=0xc2&&c<=0xdf){n=1;x=c&31;lo=128;}else if(c>=0xe0&&c<=0xef){n=2;x=c&15;lo=2048;}else if(c>=0xf0&&c<=0xf4){n=3;x=c&7;lo=65536;}else return false;if(i+n>s.size())return false;while(n--){unsigned char d=s[i++];if((d&192)!=128)return false;x=(x<<6)|(d&63);}if(x<lo||x>0x10ffff||(x>=0xd800&&x<=0xdfff))return false;}return true;}
static int hex(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}
