static bool badpath(const string&p){size_t i=0;while(i<p.size()){while(i<p.size()&&p[i]=='/')i++;size_t j=p.find('/',i);if(j==string::npos)j=p.size();if(p.substr(i,j-i)=="..")return true;i=j;}return false;}
