struct Conn{u64 id=0;int fd=-1,up=-1,file=-1;State state=READ;string in,out,upout,uphead,body,method,target,host,tenant;size_t opos=0,upos=0,bpos=0;u64 count=0,length=0,received=0,filesize=0,filepos=0,uplen=0,upgot=0,reserve=0;bool reserved=false,closing=false,head=false,connecting=false,updone=false,dead=false;i64 idle=0,headerstart=0,deadline=0,progress=0;};
static unordered_map<u64,unique_ptr<Conn>> all;
static void watch(int fd,u64 id,uint32_t flags,bool add=false){epoll_event e{};e.events=flags|EPOLLRDHUP;e.data.u64=id;epoll_ctl(ep,add?EPOLL_CTL_ADD:EPOLL_CTL_MOD,fd,&e);}
