static void closeup(Conn&c){if(c.up>=0){epoll_ctl(ep,EPOLL_CTL_DEL,c.up,nullptr);close(c.up);c.up=-1;}}
static void die(Conn&c){if(c.dead)return;c.dead=true;closeup(c);unreserve(c);epoll_ctl(ep,EPOLL_CTL_DEL,c.fd,nullptr);close(c.fd);c.fd=-1;}
static const char* reason(int n){switch(n){case 200:return "OK";case 400:return "Bad Request";case 403:return "Forbidden";case 404:return "Not Found";case 405:return "Method Not Allowed";case 408:return "Request Timeout";case 411:return "Length Required";case 413:return "Content Too Large";case 429:return "Too Many Requests";case 431:return "Request Header Fields Too Large";case 502:return "Bad Gateway";default:return "Error";}}
