static void error(Conn&c,int code,bool force=false){closeup(c);unreserve(c);c.filesize=c.filepos=0;c.body.clear();c.bpos=0;response(c,code,0,"",force);}
static void refresh(Conn&c){if(c.dead)return;uint32_t ce=0,ue=0;if(c.state==READ||c.state==UPLOAD)ce|=EPOLLIN;if(c.state==SEND)ce|=EPOLLOUT;if(c.state==STREAM&&(!c.out.empty()||c.bpos<c.body.size()))ce|=EPOLLOUT;if(c.up>=0){if(c.state==UPSTREAM){if(c.connecting||c.upos<c.upout.size()||(c.file>=0&&c.filepos<c.length))ue|=EPOLLOUT;else ue|=EPOLLIN;}else if(c.state==STREAM&&!c.updone&&c.body.size()-c.bpos<16384)ue|=EPOLLIN;watch(c.up,c.id*2+1,ue);}watch(c.fd,c.id*2,ce);}
