static bool startup(Conn&c){c.up=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(c.up<0)return false;int one=1;setsockopt(c.up,IPPROTO_TCP,TCP_NODELAY,&one,sizeof one);linger lin{1,0};setsockopt(c.up,SOL_SOCKET,SO_LINGER,&lin,sizeof lin);int r=connect(c.up,(sockaddr*)&g.origin,sizeof(g.origin));if(r<0&&errno!=EINPROGRESS){closeup(c);return false;}c.connecting=r<0;string uri=c.target.substr(8);if(uri.empty()||uri[0]=='?')uri="/"+uri;c.upout=c.method+" "+uri+" HTTP/1.1\r\nHost: "+c.host+"\r\nConnection: close\r\nContent-Length: "+to_string(c.method=="POST"?c.length:0)+"\r\n\r\n";c.upos=0;c.filepos=0;c.uphead.clear();c.updone=false;c.upgot=0;c.state=UPSTREAM;c.progress=now();watch(c.up,c.id*2+1,EPOLLIN|EPOLLOUT,true);return true;}
