static void upstream(Conn&c){if(c.up<0)return;if(c.state==UPSTREAM){if(c.connecting){int e=0;socklen_t n=sizeof(e);if(getsockopt(c.up,SOL_SOCKET,SO_ERROR,&e,&n)||e){error(c,502);return;}c.connecting=false;}for(int k=0;k<16;k++){if(c.upos<c.upout.size()){ssize_t n=send(c.up,c.upout.data()+c.upos,c.upout.size()-c.upos,MSG_NOSIGNAL);if(n>0){c.upos+=n;c.progress=now();continue;}if(n<0&&errno==EINTR)continue;if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return;error(c,502);return;}if(c.file>=0&&c.filepos<c.length){off_t off=c.filepos;ssize_t n=sendfile(c.up,c.file,&off,min<u64>(c.length-c.filepos,1<<20));if(n>0){c.filepos+=n;c.progress=now();continue;}if(n<0&&errno==EINTR)continue;if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return;error(c,502);return;}break;}}
if(c.up<0)return;if(c.state==UPSTREAM&&c.upos==c.upout.size()&&(c.file<0||c.filepos==c.length)){char b[16384];for(int k=0;k<8;k++){ssize_t n=recv(c.up,b,sizeof b,0);if(n>0){c.progress=now();c.uphead.append(b,n);if(c.uphead.size()>65536&&c.uphead.find("\r\n\r\n")==string::npos){error(c,502);return;}if(parseup(c))break;continue;}if(!n){error(c,502);return;}if(errno==EINTR)continue;if(errno==EAGAIN||errno==EWOULDBLOCK)return;error(c,502);return;}}
if(c.state==STREAM&&c.up>=0&&!c.updone){if(c.bpos){c.body.erase(0,c.bpos);c.bpos=0;}char b[16384];for(int k=0;k<8&&c.body.size()<16384;k++){size_t want=min<u64>(min<size_t>(sizeof b,16384-c.body.size()),c.uplen-c.upgot);if(!want){c.updone=true;closeup(c);break;}ssize_t n=recv(c.up,b,want,0);if(n>0){c.progress=now();c.body.append(b,n);c.upgot+=n;if(c.upgot==c.uplen){c.updone=true;closeup(c);break;}continue;}if(!n){die(c);return;}if(errno==EINTR)continue;if(errno==EAGAIN||errno==EWOULDBLOCK)break;die(c);return;}}}
int main(int argc,char**argv){signal(SIGPIPE,SIG_IGN);if(argc!=3||string(argv[1])!="--config"||!config(argv[2]))return 1;rootfd=open(g.root.c_str(),O_RDONLY|O_DIRECTORY|O_CLOEXEC);if(rootfd<0)return 1;lfd=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(lfd<0)return 1;int one=1;setsockopt(lfd,SOL_SOCKET,SO_REUSEADDR,&one,sizeof one);if(bind(lfd,(sockaddr*)&g.listen,sizeof(g.listen))||listen(lfd,4096))return 1;ep=epoll_create1(EPOLL_CLOEXEC);if(ep<0)return 1;watch(lfd,0,EPOLLIN,true);epoll_event events[1024];i64 last=now();for(;;){int n=epoll_wait(ep,events,1024,50);if(n<0){if(errno==EINTR)continue;break;}for(int i=0;i<n;i++){u64 key=events[i].data.u64;if(!key){for(;;){int fd=accept4(lfd,nullptr,nullptr,SOCK_NONBLOCK|SOCK_CLOEXEC);if(fd<0){if(errno==EINTR)continue;break;}if(all.size()>=g.maxcon){close(fd);continue;}setsockopt(fd,IPPROTO_TCP,TCP_NODELAY,&one,sizeof one);auto c=make_unique<Conn>();c->id=nextid++;c->fd=fd;c->idle=now();u64 id=c->id;all[id]=move(c);watch(fd,id*2,EPOLLIN,true);}continue;}auto it=all.find(key/2);if(it==all.end())continue;Conn&c=*it->second;if(key&1)upstream(c);else{uint32_t ev=events[i].events;if((ev&EPOLLIN)&&(c.state==READ||c.state==UPLOAD))readclient(c);if(!c.dead&&(ev&EPOLLOUT)&&(c.state==SEND||c.state==STREAM))writeclient(c);if(!c.dead&&(ev&(EPOLLERR|EPOLLHUP)))die(c);if(!c.dead&&(ev&EPOLLRDHUP)&&(c.state==READ||c.state==UPLOAD))readclient(c);}if(c.dead)all.erase(it);else refresh(c);}i64 t=now();if(t-last>=50){last=t;vector<u64> gone;for(auto&[id,ptr]:all){Conn&c=*ptr;bool changed=false;if(c.state==READ){if(c.headerstart&&t-c.headerstart>=(i64)g.headms){error(c,408,true);changed=true;}else if(!c.headerstart&&t-c.idle>=(i64)g.idlems)die(c);}else if(c.state==UPLOAD){if(t>=c.deadline){error(c,408,true);changed=true;}}else if(t-c.progress>=(i64)g.writems){if(c.state==UPSTREAM){error(c,502,true);changed=true;}else die(c);}if(c.dead)gone.push_back(id);else if(changed)refresh(c);}for(auto id:gone)all.erase(id);}}return 0;}
